-- OTOTR Finance internal review migration.
-- Headquarters expense list and full allocation/provenance detail.

create or replace function finance_api.list_pass_through_expenses(
  p_legal_entity_id uuid,p_from date,p_to date,p_status text,p_cursor text,p_limit integer
) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,finance,finance_api as $$
declare v_limit integer:=least(greatest(coalesce(p_limit,50),1),200);v_cursor_text text;v_cursor_date date;v_cursor_id uuid;v_items jsonb;v_has_more boolean;v_next text;
begin
  if not finance_api.authorize_headquarters_scope(p_legal_entity_id,'listPassThroughExpenses') then raise exception using errcode='42501',message='headquarters finance scope denied';end if;
  if p_from is not null and p_to is not null and p_from>p_to then raise exception using errcode='22023',message='invalid expense date range';end if;
  if p_status is not null and p_status not in('DRAFT','CALCULATED','PENDING_APPROVAL','APPROVED','POSTED','REVERSED') then raise exception using errcode='22023',message='invalid expense status';end if;
  if p_cursor is not null then begin v_cursor_text:=pg_catalog.convert_from(pg_catalog.decode(p_cursor,'base64'),'UTF8');if v_cursor_text!~'^\d{4}-\d{2}-\d{2}\|[0-9a-fA-F-]{36}$' then raise exception using errcode='22023',message='invalid expense cursor';end if;v_cursor_date:=pg_catalog.split_part(v_cursor_text,'|',1)::date;v_cursor_id:=pg_catalog.split_part(v_cursor_text,'|',2)::uuid;exception when others then raise exception using errcode='22023',message='invalid expense cursor';end;end if;
  with scoped as(select e.*,fd.code fee_code,fd.name fee_name,(select count(*) from finance.expense_shares s where s.pass_through_expense_id=e.id) share_count,(select count(*) from finance.document_links dl where dl.legal_entity_id=e.legal_entity_id and dl.subject_type='PASS_THROUGH_EXPENSE' and dl.subject_id=e.id) document_count from finance.pass_through_expenses e join finance.fee_definitions fd on fd.id=e.fee_definition_id where e.legal_entity_id=p_legal_entity_id and(p_from is null or e.expense_date>=p_from)and(p_to is null or e.expense_date<=p_to)and(p_status is null or e.status=p_status)and(v_cursor_date is null or(e.expense_date,e.id)<(v_cursor_date,v_cursor_id))),page as(select * from scoped order by expense_date desc,id desc limit v_limit+1),visible as(select * from page order by expense_date desc,id desc limit v_limit),projected as(select id,expense_date,pg_catalog.jsonb_build_object('expenseId',id,'expenseDate',expense_date,'supplierReference',supplier_reference,'contractualBasisReference',contractual_basis_reference,'feeCode',fee_code,'feeName',fee_name,'status',status,'sourceAmount',source_amount::text,'distributableAmount',distributable_amount::text,'currency',currency_code,'allocationMethod',allocation_policy->>'method','shareCount',share_count,'documentCount',document_count,'postingDate',posting_date,'reversalDate',reversal_date,'version',version) item from visible)
  select coalesce(pg_catalog.jsonb_agg(item order by expense_date desc,id desc),'[]'::jsonb),(select count(*)>v_limit from page),case when(select count(*)>v_limit from page)then(select pg_catalog.encode(pg_catalog.convert_to(expense_date::text||'|'||id::text,'UTF8'),'base64')from visible order by expense_date,id limit 1)else null end into v_items,v_has_more,v_next from projected;
  return pg_catalog.jsonb_build_object('items',v_items,'nextCursor',v_next,'hasMore',v_has_more);
end$$;

create or replace function finance_api.get_pass_through_expense(p_legal_entity_id uuid,p_expense_id uuid)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,finance,finance_api as $$
declare e finance.pass_through_expenses%rowtype;v_shares jsonb;v_documents jsonb;v_approval jsonb;
begin
  if not finance_api.authorize_headquarters_scope(p_legal_entity_id,'getPassThroughExpense') then raise exception using errcode='42501',message='headquarters finance scope denied';end if;
  select * into e from finance.pass_through_expenses x where x.id=p_expense_id and x.legal_entity_id=p_legal_entity_id;if not found then return null;end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('shareId',s.id,'dealerAccountId',s.dealer_account_id,'dealerCode',dle.dealer_code,'dealerName',dle.legal_name,'branchId',s.branch_id,'branchCode',b.branch_code,'allocationMethod',s.allocation_method,'distributionRuleReference',s.distribution_rule_reference,'basisValue',s.basis_value::text,'allocationRate',s.allocation_rate::text,'netAmount',s.net_amount::text,'taxAmount',s.tax_amount::text,'shareAmount',s.share_amount::text,'currency',e.currency_code,'accrualId',s.accrual_id)order by s.allocation_order),'[]'::jsonb) into v_shares from finance.expense_shares s join finance.dealer_accounts da on da.id=s.dealer_account_id join finance.dealer_legal_entities dle on dle.id=da.dealer_legal_entity_id join finance.branches b on b.id=s.branch_id where s.pass_through_expense_id=e.id;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('documentId',dr.id,'externalDocumentId',dr.external_document_id,'documentType',dr.document_type,'objectKey',dr.object_key,'contentHash',dr.content_hash)order by dr.created_at_utc),'[]'::jsonb) into v_documents from finance.document_links dl join finance.document_references dr on dr.id=dl.document_reference_id where dl.legal_entity_id=e.legal_entity_id and dl.subject_type='PASS_THROUGH_EXPENSE' and dl.subject_id=e.id and dr.status='ACTIVE';
  select pg_catalog.jsonb_build_object('requestId',ar.id,'status',ar.status,'policyVersion',ar.approval_policy_version,'preparedBy',ar.prepared_by,'stepCount',(select count(*) from finance.approval_steps st where st.approval_request_id=ar.id),'approvedStepCount',(select count(*) from finance.approval_steps st where st.approval_request_id=ar.id and st.decision='APPROVE')) into v_approval from finance.approval_requests ar where ar.legal_entity_id=e.legal_entity_id and ar.subject_type='PASS_THROUGH_EXPENSE' and ar.subject_id=e.id order by ar.created_at_utc desc,ar.id desc limit 1;
  return pg_catalog.jsonb_build_object('expenseId',e.id,'feeDefinitionId',e.fee_definition_id,'supplierReference',e.supplier_reference,'contractualBasisReference',e.contractual_basis_reference,'expenseDate',e.expense_date,'currency',e.currency_code,'source',pg_catalog.jsonb_build_object('netAmount',e.source_net_amount::text,'taxAmount',e.source_tax_amount::text,'grossAmount',e.source_amount::text),'distributable',pg_catalog.jsonb_build_object('netAmount',e.distributable_net_amount::text,'taxAmount',e.distributable_tax_amount::text,'grossAmount',e.distributable_amount::text),'allocationPolicy',e.allocation_policy,'evidenceHash',e.evidence_hash,'status',e.status,'approval',v_approval,'shares',v_shares,'documents',v_documents,'journalEntryId',e.journal_entry_id,'postingDate',e.posting_date,'reversalJournalEntryId',e.reversal_journal_entry_id,'reversalDate',e.reversal_date,'reversalReasonCode',e.reversal_reason_code,'version',e.version);
end$$;

revoke all on function finance_api.list_pass_through_expenses(uuid,date,date,text,text,integer) from public,anon;
revoke all on function finance_api.get_pass_through_expense(uuid,uuid) from public,anon;
grant execute on function finance_api.list_pass_through_expenses(uuid,date,date,text,text,integer) to authenticated;
grant execute on function finance_api.get_pass_through_expense(uuid,uuid) to authenticated;
